function a() {
  try {
    throw new Error("first");
  } catch {
    return "caught";
  } finally {
    return "override";
  }
}

function b() {
  try {
    throw new Error("first");
  } finally {
    throw new Error("second");
  }
}

console.log(a());
try {
  b();
} catch (error) {
  console.log(error.message);
}
